from torch.utils.cpp_extension import load_inline

_CUDA_SRC = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cuda_bf16.h>

// Flat grid-stride SwiGLU.  x is [N, 2*D] contiguous, y is [N, D].
template <typename scalar_t>
__global__ __launch_bounds__(256, 4)
void swiglu_flat_kernel(const scalar_t* __restrict__ x,
                        scalar_t* __restrict__ y,
                        long long total,
                        int D) {
    long long tid = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    long long stride = (long long)blockDim.x * gridDim.x;
    for (long long i = tid; i < total; i += stride) {
        long long row = i / D;
        int col = (int)(i - row * (long long)D);
        const scalar_t* xr = x + row * (long long)(2 * D);
        float gate = static_cast<float>(xr[col]);
        float up   = static_cast<float>(xr[col + D]);
        float sig = 1.0f / (1.0f + __expf(-gate));
        y[i] = static_cast<scalar_t>((gate * sig) * up);
    }
}

void swiglu_forward(torch::Tensor x, torch::Tensor y) {
    const long long N = x.size(0);
    const int D = (int)y.size(1);
    const long long total = N * (long long)D;
    if (total == 0) return;

    const int threads = 256;
    int blocks = (int)((total + threads - 1) / threads);
    // Enough blocks to fill H100 while not creating excessive launch overhead.
    blocks = blocks > 65535 ? 65535 : blocks;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

